package org.joda.time;

import java.io.*;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.convert.FromString;
import org.joda.convert.ToString;
import org.joda.time.base.BaseDateTime;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractReadableInstantFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MutableDateTime_addMonths_TriageGen2Test {

    @Test
    public void testAddPositiveMonths() {
        // Test adding 3 months to Jan 1st
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 12, 0, 0, 0);
        dt.addMonths(3);
        assertEquals(2023, dt.getYear());
        assertEquals(4, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddNegativeMonths() {
        // Test adding -3 months to June 1st
        MutableDateTime dt = new MutableDateTime(2023, 6, 1, 12, 0, 0, 0);
        dt.addMonths(-3);
        assertEquals(2023, dt.getYear());
        assertEquals(3, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsCrossingYearBoundary() {
        // Test adding 13 months to Dec 1st 2023
        MutableDateTime dt = new MutableDateTime(2023, 12, 1, 12, 0, 0, 0);
        dt.addMonths(13);
        assertEquals(2025, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsCrossingYearBoundaryNegative() {
        // Test adding -13 months to Jan 1st 2023
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 12, 0, 0, 0);
        dt.addMonths(-13);
        assertEquals(2021, dt.getYear());
        assertEquals(12, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddZeroMonths() {
        // Test adding 0 months (should remain unchanged)
        MutableDateTime dt = new MutableDateTime(2023, 5, 15, 10, 30, 0, 0);
        dt.addMonths(0);
        assertEquals(2023, dt.getYear());
        assertEquals(5, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
        assertEquals(10, dt.getHourOfDay());
        assertEquals(30, dt.getMinuteOfHour());
    }

    @Test
    public void testAddMonthsEndOfMonthHandling() {
        // Test adding 1 month to Jan 31st (should result in Feb 28th or 29th)
        MutableDateTime dt = new MutableDateTime(2023, 1, 31, 12, 0, 0, 0);
        dt.addMonths(1);
        assertEquals(2023, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(28, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsLeapYear() {
        // Test adding 1 month to Jan 31st in a leap year
        MutableDateTime dt = new MutableDateTime(2024, 1, 31, 12, 0, 0, 0);
        dt.addMonths(1);
        assertEquals(2024, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(29, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsLargeValue() {
        // Test adding a very large number of months
        MutableDateTime dt = new MutableDateTime(2000, 1, 1, 0, 0, 0, 0);
        dt.addMonths(1200); // 100 years
        assertEquals(2100, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
    }
}
